-- Economics Gen2 T4 Practice rebalancing: 20 easy / 30 medium / 20 hard.
-- Original questions never deleted; originals with historical references remain resolvable.
-- New question versions carry their own complete trilingual content and per-option diagnostics.
-- Preconditions and postconditions are enforced transactionally. Run controlled QA transaction first.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '90s';
DO $reb$
DECLARE
  payload jsonb := '[{"ref":"EC9708:G2:EC9708-G2-T4-P-005","d":"hard","sec":195,"k":"B","en":"Seven firms have market shares of 25%, 20%, 15%, 10%, 10%, 10% and 10%. Two firms each with 10% merge and no shares otherwise change. How does the four-firm concentration ratio change?","ru":"Семь компаний имеют доли рынка 25%, 20%, 15%, 10%, 10%, 10% и 10%. Две фирмы с долями по 10% объединяются, прочие доли не меняются. Как изменяется коэффициент концентрации четырёх крупнейших компаний?","uz":"Yetti firmaning bozor ulushi 25%, 20%, 15%, 10%, 10%, 10% va 10%. Har biri 10% ulushga ega ikki firma birlashadi, boshqa ulushlar o‘zgarmaydi. Eng yirik to‘rtta firma konsentratsiya ko‘rsatkichi qanday o‘zgaradi?","options_en":["Falls from 70% to 60%","Rises from 70% to 80%","Rises from 70% to 90%","Remains at 70%"],"options_ru":["Падает с 70% до 60%","Растёт с 70% до 80%","Растёт с 70% до 90%","Остаётся 70%"],"options_uz":["70% dan 60% ga tushadi","70% dan 80% ga oshadi","70% dan 90% ga oshadi","70% bo‘lib qoladi"],"why":["Initially the four largest shares total 25+20+15+10=70%. After merger they are 25,20,20,15, totalling 80%.","Сначала сумма четырёх крупнейших долей 25+20+15+10=70%; после объединения — 25+20+20+15=80%.","Dastlab eng katta to‘rt ulush 25+20+15+10=70%; birlashuvdan keyin 25+20+20+15=80%."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-007","d":"hard","sec":180,"k":"C","en":"The money-valued marginal utilities of four successive snack portions are $18, $14, $10 and $6. Every portion costs $9, with no binding income constraint. How many should a utility-maximising consumer buy, and what is total consumer surplus on those portions?","ru":"Предельная полезность четырёх последовательных порций закуски в денежном выражении равна $18, $14, $10 и $6. Каждая порция стоит $9, доход не ограничивает выбор. Сколько порций купит потребитель, максимизирующий полезность, и каков общий потребительский излишек?","uz":"Yegulikning ketma-ket to‘rtta porsiyasi pulda baholangan chegaraviy foydaliligi $18, $14, $10 va $6. Har porsiya $9 turadi, daromad cheklovi yo‘q. Foydalilikni maksimallashtiruvchi iste’molchi nechta oladi va jami iste’molchi ortiqchaligi qancha?","options_en":["4 portions; $12","2 portions; $14","3 portions; $15","3 portions; $42"],"options_ru":["4 порции; $12","2 порции; $14","3 порции; $15","3 порции; $42"],"options_uz":["4 porsiya; $12","2 porsiya; $14","3 porsiya; $15","3 porsiya; $42"],"why":["Buy units with marginal value at least $9: three units. Surplus (18−9)+(14−9)+(10−9)=$15.","Следует купить три порции с оценкой не ниже $9. Излишек (18−9)+(14−9)+(10−9)=$15.","Chegaraviy qiymati $9 dan kam bo‘lmagan uch porsiya olinadi. Ortiqchalik (18−9)+(14−9)+(10−9)=$15."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-008","d":"hard","sec":195,"k":"D","en":"A consumer has a $5 budget. Good X costs $2 per unit and has marginal utilities of 10, 8, 4 for successive units. Good Y costs $1 and has marginal utilities of 6, 3, 1. Assume whole units, at most three of each, and total utility equal to the sum of selected marginal utilities. Which affordable bundle maximises total utility?","ru":"У потребителя бюджет $5. Товар X стоит $2 за единицу и даёт последовательные предельные полезности 10, 8, 4. Товар Y стоит $1 и даёт 6, 3, 1. Можно покупать только целые единицы, максимум по три каждого товара, общая полезность — сумма предельных. Какой доступный набор даёт наибольшую полезность?","uz":"Iste’molchining budjeti $5. X mahsulot birligi $2, ketma-ket chegaraviy foydaliliklari 10, 8, 4. Y mahsulot $1, foydaliliklari 6, 3, 1. Faqat butun birlik, har biridan ko‘pi bilan uchtadan olish mumkin. Jami foydalilik chegaraviy foydaliliklar yig‘indisi. Qaysi arzon to‘plam uni maksimallashtiradi?","options_en":["1 X and 3 Y","1 X and 2 Y","2 X and 0 Y","2 X and 1 Y"],"options_ru":["1 X и 3 Y","1 X и 2 Y","2 X и 0 Y","2 X и 1 Y"],"options_uz":["1 ta X va 3 ta Y","1 ta X va 2 ta Y","2 ta X va 0 ta Y","2 ta X va 1 ta Y"],"why":["Two X cost $4 and yield 18 utils; one Y costs $1 and adds 6. Total is 24, exceeding other affordable listed combinations.","Две X стоят $4 и дают 18 единиц полезности; одна Y стоит $1 и добавляет 6. Всего 24 — больше других указанных доступных наборов.","Ikki X $4 turadi va 18 foydalilik beradi; bitta Y $1 turib yana 6 beradi. Jami 24, boshqa keltirilgan to‘plamlardan yuqori."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-009","d":"hard","sec":175,"k":"A","en":"A consumer has $120 to spend on notebooks (X) and pens (Y). A notebook costs $12 and a pen initially $6, then rises to $10. What happens to the maximum affordable number of pens, and to the absolute slope of the budget line when X is on the horizontal axis?","ru":"Потребитель располагает $120 на тетради X и ручки Y. Тетрадь стоит $12, ручка первоначально $6, затем дорожает до $10. Как изменяется максимально доступное число ручек и модуль наклона бюджетной линии при X на горизонтальной оси?","uz":"Iste’molchida X daftar va Y ruchka uchun $120 bor. Daftar $12, ruchka avval $6, keyin $10 turadi. Xarid qilish mumkin bo‘lgan eng ko‘p ruchka soni va X gorizontal o‘qda bo‘lganda budjet chizig‘i qiyaligining moduli qanday o‘zgaradi?","options_en":["Pens 20→12; slope 2→1.2","Pens 20→12; slope 1.2→2","Pens 10→12; slope 2→1.2","Pens 20→20; slope unchanged"],"options_ru":["Ручки 20→12; наклон 2→1,2","Ручки 20→12; наклон 1,2→2","Ручки 10→12; наклон 2→1,2","Ручки 20→20; наклон неизменен"],"options_uz":["Ruchka 20→12; qiyalik 2→1,2","Ruchka 20→12; qiyalik 1,2→2","Ruchka 10→12; qiyalik 2→1,2","Ruchka 20→20; qiyalik o‘zgarmaydi"],"why":["Y intercept falls from 120/6=20 to 120/10=12; absolute slope Px/Py changes from 12/6=2 to 12/10=1.2.","Пересечение оси Y падает с 120/6=20 до 120/10=12; модуль наклона Px/Py меняется с 2 до 1,2.","Y o‘qidagi kesishish 120/6=20 dan 120/10=12 ga tushadi; qiyalik moduli Px/Py 2 dan 1,2 ga o‘zgaradi."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-014","d":"hard","sec":165,"k":"B","en":"A manufacturer cannot change plant size this month but can add workers. Over three years it builds a larger plant; output doubles from 100 to 200 units while total cost rises from $1,200 to $2,000 at unchanged factor prices. What is the best interpretation?","ru":"Производитель в течение месяца не может изменить размеры завода, но может нанимать работников. За три года он строит более крупный завод: выпуск растёт со 100 до 200 изделий, общие затраты — с $1 200 до $2 000 при неизменных ценах ресурсов. Какая интерпретация верна?","uz":"Korxona bir oyda zavod hajmini o‘zgartira olmaydi, ammo ishchi qo‘sha oladi. Uch yil ichida katta zavod quradi: ishlab chiqarish 100 dan 200 taga, jami xarajat $1200 dan $2000 ga oshadi, omil narxlari o‘zgarmaydi. Qaysi talqin to‘g‘ri?","options_en":["Short-run expansion; average cost rises by $2","Long-run expansion; average cost falls from $12 to $10","Long-run expansion; average cost rises from $10 to $12","Short-run movement; total fixed cost necessarily becomes zero"],"options_ru":["Краткосрочное расширение; средние затраты растут на $2","Долгосрочное расширение; средние затраты падают с $12 до $10","Долгосрочное расширение; средние затраты растут с $10 до $12","Краткосрочное изменение; постоянные затраты становятся нулевыми"],"options_uz":["Qisqa muddatli kengayish; o‘rtacha xarajat $2 ga oshadi","Uzoq muddatli kengayish; o‘rtacha xarajat $12 dan $10 ga tushadi","Uzoq muddatli kengayish; o‘rtacha xarajat $10 dan $12 ga oshadi","Qisqa muddatli o‘zgarish; doimiy xarajat nol bo‘ladi"],"why":["Plant size changes only in the long run. Average cost falls from 1200/100=$12 to 2000/200=$10, consistent with economies of scale.","Размер завода меняется в долгосрочном периоде. Средние затраты падают с 1200/100=$12 до 2000/200=$10 — эффект масштаба.","Zavod hajmi uzoq muddatda o‘zgaradi. O‘rtacha xarajat 1200/100=$12 dan 2000/200=$10 ga tushadi; miqyos tejamkorligi."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-016","d":"hard","sec":175,"k":"D","en":"Bundles A (4 units of X and 8 of Y) and B (8 of X and 4 of Y) lie on the same indifference curve. Prices are Px=$10 and Py=$5; the consumer''s budget is $80. Which conclusion follows about utility and affordability?","ru":"Наборы A (4 единицы X и 8 единиц Y) и B (8 единиц X и 4 единицы Y) лежат на одной кривой безразличия. Цены Px=$10, Py=$5, бюджет $80. Какой вывод следует о полезности и доступности?","uz":"A (4 ta X va 8 ta Y) hamda B (8 ta X va 4 ta Y) to‘plamlari bir befarqlik egri chizig‘ida. Px=$10, Py=$5, budjet $80. Foydalilik va xarid qilish imkoni haqida qaysi xulosa to‘g‘ri?","options_en":["B gives higher utility and both bundles are affordable","A gives higher utility, but neither bundle is affordable","Utility is equal and both bundles cost $80","Utility is equal, A costs $80 and B costs $100, so only A is affordable"],"options_ru":["B полезнее, оба набора доступны","A полезнее, но ни один набор недоступен","Полезность одинакова, оба стоят $80","Полезность одинакова; A стоит $80, B — $100, доступен только A"],"options_uz":["B foydaliroq, ikkalasini ham olish mumkin","A foydaliroq, ikkalasini ham olish mumkin emas","Foydalilik teng, ikkalasi $80 turadi","Foydalilik teng; A $80, B $100, faqat A arzon"],"why":["Equal indifference curve implies equal preference rank. Cost A=4×10+8×5=$80; cost B=8×10+4×5=$100.","Одна кривая безразличия означает равную полезность. Стоимость A=4×10+8×5=$80; B=8×10+4×5=$100.","Bir befarqlik egri chizig‘i bir xil foydalilikni bildiradi. A=4×10+8×5=$80, B=8×10+4×5=$100."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-017","d":"hard","sec":190,"k":"C","en":"For one extra unit of output, a factory''s marginal private cost is $30 and marginal external harm $12. Buyers'' marginal private benefit is $45, and the unit also generates a marginal external benefit of $4. Assuming no other effects, what are marginal social cost and marginal net social benefit of producing this unit?","ru":"При выпуске дополнительной единицы продукции предельные частные затраты завода $30, внешний ущерб $12. Предельная частная выгода покупателей $45, дополнительная внешняя выгода $4. Других эффектов нет. Найдите предельные общественные затраты и чистую предельную общественную выгоду выпуска этой единицы.","uz":"Qo‘shimcha mahsulot birligi uchun zavodning chegaraviy xususiy xarajati $30, tashqi zarari $12. Xaridorlarning chegaraviy xususiy foydasi $45, qo‘shimcha tashqi foyda $4. Boshqa ta’sir yo‘q. Ushbu birlikning chegaraviy ijtimoiy xarajati va sof chegaraviy ijtimoiy foydasi qancha?","options_en":["Social cost $18; net benefit $27","Social cost $42; net benefit −$3","Social cost $42; net benefit +$7","Social cost $30; net benefit +$19"],"options_ru":["Общественные затраты $18; чистая выгода $27","Общественные затраты $42; чистая выгода −$3","Общественные затраты $42; чистая выгода +$7","Общественные затраты $30; чистая выгода +$19"],"options_uz":["Ijtimoiy xarajat $18; sof foyda $27","Ijtimoiy xarajat $42; sof foyda −$3","Ijtimoiy xarajat $42; sof foyda +$7","Ijtimoiy xarajat $30; sof foyda +$19"],"why":["MSC=30+12=$42; MSB=45+4=$49. Net social marginal benefit=49−42=$7.","MSC=30+12=$42; MSB=45+4=$49. Чистая предельная выгода=49−42=$7.","MSC=30+12=$42; MSB=45+4=$49. Sof chegaraviy foyda=49−42=$7."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-021","d":"hard","sec":175,"k":"A","en":"A loud outdoor concert gives an extra attendee marginal private benefit valued at $60; private marginal cost is $20, but added noise imposes $50 in harm on neighbours. Ignore other effects. What is the net social benefit of admitting one more attendee, and what follows at this margin?","ru":"Дополнительный посетитель уличного концерта получает предельную личную выгоду $60, предельные частные издержки равны $20, но шум наносит соседям ущерб $50. Других эффектов нет. Какова чистая общественная выгода ещё одного посетителя и какой вывод следует?","uz":"Ochiq konsertga yana bir tashrif buyuruvchining chegaraviy shaxsiy foydasi $60, xususiy xarajati $20, ammo shovqin qo‘shnilarga $50 zarar yetkazadi. Boshqa ta’sir yo‘q. Yana bir kishini kiritishning sof ijtimoiy foydasi qancha va qanday xulosa kelib chiqadi?","options_en":["−$10; the extra attendance is socially undesirable at this margin","+$40; private gain proves social efficiency","+$90; all benefits and costs must be added","−$50; private benefits cannot count toward social welfare"],"options_ru":["−$10; дополнительный посетитель на этом пределе нежелателен для общества","+$40; личная выгода доказывает общественную эффективность","+$90; следует сложить все выгоды и затраты","−$50; личные выгоды нельзя учитывать в общественном благосостоянии"],"options_uz":["−$10; yana bir tashrif ijtimoiy jihatdan nomaqbul","+$40; shaxsiy foyda ijtimoiy samaradorlikni isbotlaydi","+$90; barcha foyda va xarajat qo‘shiladi","−$50; shaxsiy foyda ijtimoiy farovonlikka kiritilmaydi"],"why":["Marginal social benefit net of costs is 60−20−50=−$10. Private gain (60−20) is positive but ignores neighbours'' losses.","Чистая предельная общественная выгода 60−20−50=−$10. Положительная личная выгода игнорирует ущерб соседям.","Sof chegaraviy ijtimoiy foyda 60−20−50=−$10. Shaxsiy foyda musbat, lekin qo‘shni zarari hisobga olinmagan."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-025","d":"hard","sec":180,"k":"B","en":"A firm compares three long-run plants at unchanged input prices: plant A produces 100 units for total cost $1,000; plant B 200 units for $1,800; plant C 300 units for $3,300. Which cost pattern is supported?","ru":"Фирма сравнивает три завода в долгосрочном периоде при неизменных ценах ресурсов: A выпускает 100 единиц при затратах $1 000; B — 200 при $1 800; C — 300 при $3 300. Какой характер изменения средних затрат подтверждается?","uz":"Firma uzoq muddatda resurs narxlari o‘zgarmaganda uch zavodni solishtiradi: A 100 birlikni $1000 ga, B 200 birlikni $1800 ga, C 300 birlikni $3300 ga ishlab chiqaradi. O‘rtacha xarajat qanday o‘zgaradi?","options_en":["Average cost always falls as scale rises","Average cost falls from $10 to $9, then rises to $11","Average cost rises from $10 to $18, then to $33","Average cost remains $10 at all three sizes"],"options_ru":["Средние затраты всегда падают с масштабом","Средние затраты падают с $10 до $9, затем растут до $11","Средние затраты растут с $10 до $18, затем до $33","Средние затраты остаются $10 для всех заводов"],"options_uz":["Miqyos oshganda o‘rtacha xarajat doim tushadi","O‘rtacha xarajat $10 dan $9 ga tushib, keyin $11 ga oshadi","O‘rtacha xarajat $10 dan $18 ga, keyin $33 ga oshadi","Hamma zavodda o‘rtacha xarajat $10 bo‘ladi"],"why":["ATC is 1000/100=$10, 1800/200=$9, and 3300/300=$11. The firm first gains and then loses economies of scale.","Средние затраты 1000/100=$10, 1800/200=$9 и 3300/300=$11. Сначала экономия от масштаба, затем отрицательный эффект масштаба.","O‘rtacha xarajat 1000/100=$10, 1800/200=$9, 3300/300=$11. Avval miqyos tejamkorligi, keyin tejamkorlikning yo‘qolishi."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-027","d":"hard","sec":205,"k":"D","en":"Demand for vaccinations based only on private benefit is Qd=80−P, and marginal private supply cost is given by P=20+Q. Each vaccination generates an additional constant external benefit of $20. In this simplified competitive model, what are the market quantity, socially efficient quantity and corrective per-unit subsidy?","ru":"Спрос на вакцинацию на основе лишь личной выгоды Qd=80−P, предельные частные затраты предложения P=20+Q. Каждая прививка создаёт постоянную дополнительную внешнюю выгоду $20. В упрощённой конкурентной модели найдите рыночный объём, общественно эффективный объём и корректирующую субсидию на единицу.","uz":"Emlashga faqat shaxsiy foydaga asoslangan talab Qd=80−P, taklifning chegaraviy xususiy xarajati P=20+Q. Har emlash doimiy $20 qo‘shimcha tashqi foyda yaratadi. Soddalashtirilgan raqobat modelida bozor miqdori, ijtimoiy samarali miqdor va birlik subsidiyasi qancha?","options_en":["30; 30; $20","40; 50; $10","30; 50; $10","30; 40; $20"],"options_ru":["30; 30; $20","40; 50; $10","30; 50; $10","30; 40; $20"],"options_uz":["30; 30; $20","40; 50; $10","30; 50; $10","30; 40; $20"],"why":["Inverse private demand is P=80−Q; equating with 20+Q gives Q=30. With external benefit, MSB=100−Q, giving efficient Q=40. Corrective subsidy equals $20.","Обратный частный спрос P=80−Q. При равенстве с 20+Q рынок Q=30. При внешней выгоде MSB=100−Q, общественный оптимум Q=40; субсидия $20.","Teskari xususiy talab P=80−Q; 20+Q bilan tenglashtirib Q=30. Tashqi foyda bilan MSB=100−Q, samarali Q=40, subsidiya $20."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-028","d":"hard","sec":185,"k":"C","en":"At output Q, marginal social benefit is MSB=100−2Q and marginal social cost is MSC=10+Q. Production is currently Q=20. What is the efficient quantity, and is one additional unit at Q=20 socially worthwhile at the margin?","ru":"При выпуске Q предельная общественная выгода MSB=100−2Q, а предельные общественные затраты MSC=10+Q. Сейчас Q=20. Найдите эффективный объём и определите, выгодна ли обществу ещё одна единица при текущем Q.","uz":"Q miqdorda chegaraviy ijtimoiy foyda MSB=100−2Q, chegaraviy ijtimoiy xarajat MSC=10+Q. Hozir Q=20. Samarali miqdor qancha va Q=20 darajada qo‘shimcha birlik jamiyat uchun foydalimi?","options_en":["Efficient Q=20; additional production causes a $30 social loss","Efficient Q=45; no additional production is desirable","Efficient Q=30; at Q=20 marginal net benefit is +$30","Efficient Q=30; at Q=20 marginal net benefit is −$30"],"options_ru":["Оптимум Q=20; новая единица даёт общественный убыток $30","Оптимум Q=45; новый выпуск не нужен","Оптимум Q=30; при Q=20 чистая предельная выгода +$30","Оптимум Q=30; при Q=20 чистая предельная выгода −$30"],"options_uz":["Optimal Q=20; qo‘shimcha birlik $30 ijtimoiy zarar beradi","Optimal Q=45; qo‘shimcha mahsulot kerak emas","Optimal Q=30; Q=20 da sof chegaraviy foyda +$30","Optimal Q=30; Q=20 da sof chegaraviy foyda −$30"],"why":["Set MSB=MSC: 100−2Q=10+Q, Q=30. At Q=20, benefit=60 and cost=30, so net social gain=+$30.","MSB=MSC: 100−2Q=10+Q, Q=30. При Q=20 выгода 60, затраты 30, чистый общественный выигрыш +$30.","MSB=MSC: 100−2Q=10+Q, Q=30. Q=20 da foyda 60, xarajat 30, sof ijtimoiy foyda +$30."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-031","d":"hard","sec":175,"k":"B","en":"For a proposed extra unit, marginal social cost is $70 and marginal external cost is $18. The unit brings consumers a marginal benefit of $60, with no external benefit. What are marginal private cost and the social net gain/loss, and might a private producer still supply it?","ru":"Для предлагаемой дополнительной единицы предельные общественные затраты $70, внешние предельные затраты $18. Предельная выгода потребителей $60, внешней выгоды нет. Найдите частные затраты и чистый общественный эффект. Может ли частный производитель всё же предложить эту единицу?","uz":"Taklif etilgan qo‘shimcha birlikning chegaraviy ijtimoiy xarajati $70, tashqi xarajati $18. Xaridorlarning chegaraviy foydasi $60, tashqi foyda yo‘q. Xususiy xarajat va sof ijtimoiy natija qanday? Xususiy ishlab chiqaruvchi uni baribir taklif qilishi mumkinmi?","options_en":["Private cost $88; social gain +$10; private supply impossible","Private cost $52; social loss $10; private supply may still occur","Private cost $52; social gain +$8; social production must expand","Private cost $18; social loss $70; private supply impossible"],"options_ru":["Частные затраты $88; общественная выгода +$10; частный выпуск невозможен","Частные затраты $52; общественный убыток $10; частный выпуск возможен","Частные затраты $52; общественная выгода +$8; выпуск обязательно надо увеличить","Частные затраты $18; общественный убыток $70; частный выпуск невозможен"],"options_uz":["Xususiy xarajat $88; ijtimoiy foyda +$10; xususiy taklif mumkin emas","Xususiy xarajat $52; ijtimoiy zarar $10; xususiy taklif bo‘lishi mumkin","Xususiy xarajat $52; ijtimoiy foyda +$8; ishlab chiqarish albatta ko‘payishi kerak","Xususiy xarajat $18; ijtimoiy zarar $70; xususiy taklif mumkin emas"],"why":["MPC=MSC−MEC=70−18=$52. Private margin is 60−52=+$8, but social margin 60−70=−$10; overproduction can occur.","MPC=70−18=$52. Частный результат 60−52=+$8, но общественный 60−70=−$10; возможен избыточный выпуск.","MPC=70−18=$52. Xususiy foyda 60−52=+$8, ijtimoiy natija 60−70=−$10; ortiqcha ishlab chiqarish mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-033","d":"hard","sec":185,"k":"A","en":"A business sells 100 units at $20 each. Explicit fixed cost is $250 and variable cost is $14 per unit. The owner''s next-best alternative use of resources would earn $500. What are accounting profit and economic profit?","ru":"Фирма продаёт 100 изделий по $20. Явные постоянные затраты $250, переменные затраты $14 на изделие. Лучшее альтернативное использование ресурсов владельца принесло бы $500. Найдите бухгалтерскую и экономическую прибыль.","uz":"Firma 100 ta mahsulotni $20 dan sotadi. Aniq doimiy xarajat $250, o‘zgaruvchi xarajat har birlik uchun $14. Egasi resurslarining eng yaxshi muqobil ishlatilishi $500 foyda keltirishi mumkin edi. Buxgalteriya va iqtisodiy foyda qancha?","options_en":["Accounting profit +$350; economic profit −$150","Accounting profit +$600; economic profit +$100","Accounting profit −$150; economic profit +$350","Accounting profit +$350; economic profit +$850"],"options_ru":["Бухгалтерская прибыль +$350; экономическая −$150","Бухгалтерская прибыль +$600; экономическая +$100","Бухгалтерская прибыль −$150; экономическая +$350","Бухгалтерская прибыль +$350; экономическая +$850"],"options_uz":["Buxgalteriya foydasi +$350; iqtisodiy foyda −$150","Buxgalteriya foydasi +$600; iqtisodiy foyda +$100","Buxgalteriya foydasi −$150; iqtisodiy foyda +$350","Buxgalteriya foydasi +$350; iqtisodiy foyda +$850"],"why":["Revenue =100×$20=$2,000. Explicit costs=$250+100×$14=$1,650, so accounting profit=$350. Economic profit=$350−$500=−$150.","Выручка $2 000, явные затраты $250+$1 400=$1 650, бухгалтерская прибыль $350. После неявной альтернативной стоимости $500 экономическая прибыль −$150.","Tushum $2000, aniq xarajat $250+$1400=$1650, buxgalteriya foydasi $350. $500 muqobil xarajat hisoblangach iqtisodiy foyda −$150."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-035","d":"hard","sec":165,"k":"D","en":"A workshop with five workers makes 200 loaves daily; with six workers it makes 228; with seven it makes 245, with capital unchanged. What are the marginal products of the sixth and seventh workers, and what pattern do they illustrate?","ru":"Пекарня при пяти работниках выпускает 200 буханок в день, при шести — 228, при семи — 245; капитал неизменен. Найдите предельную производительность шестого и седьмого работников и определите закономерность.","uz":"Nonvoyxonada besh ishchi kuniga 200 non, olti ishchi 228, yetti ishchi 245 non tayyorlaydi; kapital o‘zgarmaydi. Oltinchi va yettinchi ishchining chegaraviy mahsuloti qancha va qanday qonuniyat kuzatiladi?","options_en":["28 and 45; increasing marginal returns","38 and 35; constant returns","28 and 17; increasing marginal returns","28 and 17; diminishing marginal returns"],"options_ru":["28 и 45; возрастающая предельная отдача","38 и 35; постоянная отдача","28 и 17; возрастающая предельная отдача","28 и 17; убывающая предельная отдача"],"options_uz":["28 va 45; chegaraviy qaytim o‘sadi","38 va 35; qaytim o‘zgarmaydi","28 va 17; chegaraviy qaytim o‘sadi","28 va 17; chegaraviy qaytim kamayadi"],"why":["Sixth worker contributes 228−200=28; seventh 245−228=17. Marginal product falls as more labour uses fixed capital.","Шестой работник добавляет 228−200=28, седьмой 245−228=17. Предельная отдача снижается при неизменном капитале.","Oltinchi ishchi 228−200=28, yettinchi 245−228=17 birlik qo‘shadi. Kapital o‘zgarmaganda chegaraviy mahsulot kamayadi."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-042","d":"hard","sec":175,"k":"C","en":"A printer has weekly fixed costs of $150 and variable cost $9 per poster; posters sell for $15 each. How many posters must be sold to break even, and what is profit if 40 are sold, ignoring other costs?","ru":"У типографии недельные постоянные затраты $150, переменные $9 на плакат, цена продажи $15 за плакат. Сколько плакатов нужно продать для безубыточности и какова прибыль от продажи 40 плакатов, без других затрат?","uz":"Bosmaxonaning haftalik doimiy xarajati $150, har plakat o‘zgaruvchi xarajati $9, sotuv narxi $15. Zararsizlik uchun nechta plakat sotish kerak va 40 tasi sotilsa boshqa xarajatlarsiz foyda qancha?","options_en":["15 posters; profit $240","25 posters; profit $240","25 posters; profit $90","40 posters; profit $90"],"options_ru":["15 плакатов; прибыль $240","25 плакатов; прибыль $240","25 плакатов; прибыль $90","40 плакатов; прибыль $90"],"options_uz":["15 plakat; foyda $240","25 plakat; foyda $240","25 plakat; foyda $90","40 plakat; foyda $90"],"why":["Contribution margin =15−9=$6 per poster. Break-even 150/6=25; profit at 40 is 40×6−150=$90.","Маржинальный доход на плакат 15−9=$6. Безубыточность 150/6=25; прибыль при 40: 40×6−150=$90.","Har plakat hissasi 15−9=$6. Zararsizlik 150/6=25; 40 ta sotilganda foyda 40×6−150=$90."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-045","d":"hard","sec":175,"k":"A","en":"At the current margin, a vaccination costs $45 to provide and the consumer''s private benefit is $40. Reduced infections create an additional $15 benefit for others. With no other effects, what is the net social benefit of that marginal vaccination, and can private demand be too low?","ru":"На данном пределе вакцинация обходится в $45, личная выгода получателя $40, снижение заражений создаёт дополнительную выгоду другим людям $15. Других эффектов нет. Какова чистая общественная выгода этой прививки и может ли частный спрос быть недостаточным?","uz":"Ushbu chegarada emlash xarajati $45, oluvchining shaxsiy foydasi $40, yuqtirishning kamayishi boshqalarga qo‘shimcha $15 foyda beradi. Boshqa ta’sir yo‘q. Shu emlashning sof ijtimoiy foydasi qancha va xususiy talab yetarli bo‘lmasligi mumkinmi?","options_en":["+$10; yes, private demand can underprovide it","−$5; no, private demand always matches the optimum","+55; no, private benefits equal social benefits","+15; yes, cost is irrelevant to efficiency"],"options_ru":["+ $10; да, частный спрос может недооценивать полезный выпуск","−$5; нет, частный спрос всегда оптимален","+$55; нет, личная и общественная выгоды равны","+$15; да, затраты не важны для эффективности"],"options_uz":["+ $10; ha, xususiy talab yetarli bo‘lmasligi mumkin","−$5; yo‘q, xususiy talab har doim optimal","+$55; yo‘q, shaxsiy va ijtimoiy foyda teng","+$15; ha, xarajat samaradorlik uchun muhim emas"],"why":["Social benefit=40+15=$55; cost=$45, so marginal net benefit=+$10. Private benefit $40 is below cost and may lead to underconsumption.","Общественная выгода 40+15=$55 при затратах $45, чистая выгода +$10. Личная выгода $40 ниже издержек, поэтому возможно недопотребление.","Ijtimoiy foyda 40+15=$55, xarajat $45, sof foyda +$10. Shaxsiy foyda $40 xarajatdan pastligi kam iste’molga olib kelishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-053","d":"hard","sec":195,"k":"B","en":"Successive pastries have money-valued marginal utilities $12, $8, $5 and $2. Initially each costs $6; later the price falls to $4. Assume no income constraint. By how much does the consumer''s maximum net utility (total willingness to pay minus expenditure) increase?","ru":"Денежная оценка предельной полезности последовательных пирожных равна $12, $8, $5 и $2. Первоначально цена $6 за штуку, затем снижается до $4. Доход не ограничивает выбор. На сколько возрастает максимальная чистая полезность (готовность платить минус расходы)?","uz":"Ketma-ket pishiriqlarning puldagi chegaraviy foydaliligi $12, $8, $5 va $2. Dastlab narx $6, keyin $4 ga tushadi. Daromad cheklovi yo‘q. Maksimal sof foydalilik (to‘lashga tayyorlik minus xarajat) qanchaga ortadi?","options_en":["$2","$5","$8","$13"],"options_ru":["$2","$5","$8","$13"],"options_uz":["$2","$5","$8","$13"],"why":["At $6 buy 2: surplus=(12−6)+(8−6)=$8. At $4 buy 3: (12−4)+(8−4)+(5−4)=$13. Gain=$5.","При цене $6 покупаются 2 пирожных: излишек $8. При $4 покупаются 3: излишек $13. Прирост $5.","$6 narxda 2 ta olinadi: ortiqchalik $8. $4 narxda 3 ta olinadi: ortiqchalik $13. Oshish $5."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-058","d":"hard","sec":195,"k":"D","en":"Supplying a city''s 100 households through a water network costs $1,000 fixed plus $2 per household. If two duplicate networks each serve 50 households, each incurs the same fixed cost. How much does one network save relative to two, and which structure does the calculation support?","ru":"Сеть водоснабжения для 100 домохозяйств требует постоянных затрат $1 000 и $2 на подключённый дом. Если две дублирующие сети обслуживают по 50 домов, каждая несёт такие же постоянные затраты. Какова экономия одной сети и какую структуру рынка подтверждает расчёт?","uz":"Shaharning 100 xonadonini suv bilan ta’minlash uchun tarmoq $1000 doimiy xarajat va har xonadonga $2 sarf talab qiladi. Ikki takroriy tarmoq 50 tadan xonadonga xizmat qilsa, har biri bir xil doimiy xarajatni qiladi. Bitta tarmoq qancha tejaydi va bu qaysi bozor tuzilmasini qo‘llab-quvvatlaydi?","options_en":["$200 saving; perfect competition","$0 saving; monopolistic competition","$2,000 saving; price-taking monopoly","$1,000 saving; natural-monopoly cost advantage"],"options_ru":["Экономия $200; совершенная конкуренция","Экономия $0; монополистическая конкуренция","Экономия $2 000; монополия-ценополучатель","Экономия $1 000; преимущество естественной монополии"],"options_uz":["$200 tejaladi; mukammal raqobat","$0 tejaladi; monopolistik raqobat","$2000 tejaladi; narx qabul qiluvchi monopoliya","$1000 tejaladi; tabiiy monopoliya xarajat ustunligi"],"why":["One network costs 1000+2×100=$1,200; two cost 2×(1000+2×50)=$2,200. The $1,000 saving supports natural monopoly.","Одна сеть обходится в $1 200, две — в 2×$1 100=$2 200. Экономия $1 000 указывает на издержечное преимущество естественной монополии.","Bitta tarmoq $1200, ikkita tarmoq 2×$1100=$2200 turadi. $1000 tejamkorlik tabiiy monopoliya xarajat ustunligini ko‘rsatadi."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-060","d":"hard","sec":205,"k":"C","en":"Demand is P=80−Q and marginal private supply cost P=20+Q. Production creates marginal external harm of $10 per unit. In the simple competitive model, what are the unregulated market quantity, socially efficient quantity and Pigouvian tax per unit?","ru":"Спрос задан P=80−Q, предельные частные затраты предложения P=20+Q. Производство каждой единицы создаёт внешний ущерб $10. В простой конкурентной модели найдите нерегулируемый рыночный объём, общественно эффективный объём и корректирующий налог на единицу.","uz":"Talab P=80−Q, taklifning chegaraviy xususiy xarajati P=20+Q. Har birlik ishlab chiqarish $10 tashqi zarar yetkazadi. Oddiy raqobat modelida tartibga solinmagan bozor miqdori, ijtimoiy optimal miqdor va birlik uchun Pigou solig‘i qancha?","options_en":["30; 30; $10","25; 30; $5","30; 25; $10","30; 20; $20"],"options_ru":["30; 30; $10","25; 30; $5","30; 25; $10","30; 20; $20"],"options_uz":["30; 30; $10","25; 30; $5","30; 25; $10","30; 20; $20"],"why":["Without tax 80−Q=20+Q gives Q=30. With MSC=30+Q, 80−Q=30+Q yields Q=25. Corrective tax equals marginal harm $10.","Без налога 80−Q=20+Q даёт Q=30. При общественных затратах 30+Q оптимум Q=25. Корректирующий налог равен ущербу $10.","Soliqsiz 80−Q=20+Q dan Q=30. MSC=30+Q bilan samarali Q=25. Tuzatuvchi soliq tashqi zararga, $10 ga teng."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-065","d":"hard","sec":160,"k":"B","en":"A price-taking producer sells each unit for $12. Its marginal costs for the 6th, 7th and 8th units are $10, $11 and $14 respectively, and the firm currently produces five units. Assuming no other changes, how many extra units should it produce to maximise profit and what additional profit do they generate?","ru":"Фирма-ценополучатель продаёт каждое изделие по $12. Предельные затраты шестого, седьмого и восьмого изделий равны $10, $11 и $14. Сейчас фирма выпускает пять изделий. Сколько дополнительных изделий следует произвести для максимизации прибыли и каков прирост прибыли?","uz":"Narx qabul qiluvchi firma har mahsulotni $12 dan sotadi. Oltinchi, yettinchi va sakkizinchi birlikning chegaraviy xarajati $10, $11, $14. Firma hozir beshta ishlab chiqaradi. Foydani maksimallashtirish uchun yana nechta chiqarish va qo‘shimcha foyda qancha bo‘ladi?","options_en":["3 units; $3 additional profit","2 units; $3 additional profit","2 units; $24 additional profit","1 unit; $2 additional profit"],"options_ru":["3 изделия; прирост прибыли $3","2 изделия; прирост прибыли $3","2 изделия; прирост прибыли $24","1 изделие; прирост прибыли $2"],"options_uz":["3 birlik; qo‘shimcha foyda $3","2 birlik; qo‘shimcha foyda $3","2 birlik; qo‘shimcha foyda $24","1 birlik; qo‘shimcha foyda $2"],"why":["The sixth adds $12−$10=$2, the seventh adds $12−$11=$1; the eighth would reduce profit by $2. Add two units for $3.","Шестое изделие добавляет $2 прибыли, седьмое $1, восьмое снизило бы прибыль на $2. Нужны две дополнительные единицы и прирост $3.","Oltinchi birlik +$2, yettinchi +$1, sakkizinchi −$2 foyda keltiradi. Ikki birlik qo‘shib $3 foyda olinadi."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-004","d":"medium","sec":145,"k":"C","en":"In a perfectly competitive wheat market the price is $18 per tonne. One small farm sells 100 tonnes at this price. Its manager considers charging $20 while rivals still sell identical wheat for $18. If buyers can switch without cost, which comparison is most plausible?","ru":"На совершенно конкурентном рынке пшеницы цена составляет $18 за тонну. Небольшая ферма продаёт 100 тонн по этой цене. Управляющий собирается поднять цену до $20, хотя конкуренты продают идентичную пшеницу по $18 и покупатели могут свободно переключаться. Какой результат наиболее вероятен?","uz":"Mukammal raqobatli bug‘doy bozorida narx bir tonnaga $18. Kichik fermer 100 tonnani shu narxda sotadi. Raqiblar bir xil bug‘doyni $18 dan sotayotganida menejer narxni $20 ga oshirmoqchi; xaridorlar hech qanday xarajatsiz boshqa sotuvchiga o‘ta oladi. Qaysi natija eng ehtimoliy?","options_en":["Revenue rises from $1,800 to $2,000 with unchanged sales","The farm creates an industry monopoly by raising its price","The farm risks losing almost all sales rather than gaining $200 revenue","Every other farm must raise its price to $20"],"options_ru":["Выручка возрастёт с $1 800 до $2 000 без изменения продаж","Ферма станет монополистом, подняв цену","Ферма рискует потерять почти все продажи вместо получения дополнительных $200","Все конкуренты обязаны повысить цены до $20"],"options_uz":["Tushum savdo o‘zgarmasdan $1800 dan $2000 ga oshadi","Fermer narxni oshirib monopoliya yaratadi","Fermer qo‘shimcha $200 olish o‘rniga deyarli barcha savdoni yo‘qotishi mumkin","Barcha raqiblar narxni $20 ga oshirishi shart"],"why":["At the common price revenue is 100×$18=$1,800. A single price-taking seller cannot sustainably charge more for identical goods when buyers can switch.","При общей цене выручка 100×$18=$1 800. Отдельный продавец-ценополучатель не сможет удержать более высокую цену на одинаковый товар при свободном переходе покупателей.","Umumiy narxda tushum 100×$18=$1800. Narx qabul qiluvchi sotuvchi bir xil tovar uchun raqiblardan qimmatroq narxni ushlab turolmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-012","d":"medium","sec":145,"k":"B","en":"A food company builds two new bakeries using retained profits and also buys an existing flour mill. How should these two expansion decisions be classified, in the order described?","ru":"Продовольственная компания строит две новые пекарни за счёт нераспределённой прибыли, а также покупает действующую мельницу, которая поставляет муку. Как классифицировать два решения о росте в указанном порядке?","uz":"Oziq-ovqat firmasi taqsimlanmagan foydasi hisobiga ikkita yangi nonvoyxona quradi va un yetkazib beruvchi mavjud tegirmonni sotib oladi. Ushbu ikki kengayish usuli ketma-ket qanday tasniflanadi?","options_en":["Horizontal integration; internal growth","Organic growth; backward vertical integration","Forward vertical integration; organic growth","Conglomerate integration; horizontal integration"],"options_ru":["Горизонтальная интеграция; внутренний рост","Органический рост; обратная вертикальная интеграция","Прямая вертикальная интеграция; органический рост","Конгломератная интеграция; горизонтальная интеграция"],"options_uz":["Gorizontal integratsiya; ichki o‘sish","Organik o‘sish; orqaga vertikal integratsiya","Oldinga vertikal integratsiya; organik o‘sish","Konglomerat integratsiya; gorizontal integratsiya"],"why":["Building new owned capacity is organic growth; buying a supplier upstream in the production chain is backward vertical integration.","Строительство собственных новых объектов — органический рост; покупка поставщика на предыдущем этапе цепочки — обратная вертикальная интеграция.","Yangi o‘z quvvatini qurish organik o‘sish, ta’minotchini sotib olish esa orqaga vertikal integratsiyadir."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-015","d":"medium","sec":155,"k":"A","en":"A city has many cafés offering different menus and atmospheres with relatively easy entry. One café introduces a unique menu and raises its price modestly, while some customers still prefer it. Which combination best describes the market structure and source of limited price-setting power?","ru":"В городе много кафе с разными меню и атмосферой, вход на рынок относительно свободен. Одно кафе создаёт уникальное меню и немного повышает цену, но часть клиентов остаётся. Какая пара лучше описывает структуру рынка и источник ограниченной ценовой власти?","uz":"Shaharda turli menyu va muhitga ega ko‘plab kafelar bor, bozorga kirish nisbatan oson. Bitta kafe noyob menyu yaratib narxini biroz oshiradi, lekin ayrim mijozlar baribir qoladi. Bozor tuzilmasi va cheklangan narx belgilash kuchi manbai qanday?","options_en":["Monopolistic competition; product differentiation","Perfect competition; identical products","Pure monopoly; legal exclusion of all rivals","Monopsony; a single buyer sets café prices"],"options_ru":["Монополистическая конкуренция; дифференциация продукта","Совершенная конкуренция; идентичный продукт","Чистая монополия; законодательно исключены все конкуренты","Монопсония; один покупатель устанавливает цены кафе"],"options_uz":["Monopolistik raqobat; mahsulot tabaqalanishi","Mukammal raqobat; bir xil mahsulotlar","Sof monopoliya; raqiblar qonuniy taqiqlangan","Monopsoniya; bitta xaridor kafe narxini belgilaydi"],"why":["Many sellers and ease of entry are consistent with monopolistic competition; differentiation creates some customer loyalty and limited pricing discretion.","Множество продавцов и свободный вход соответствуют монополистической конкуренции; различия продукта создают лояльность и ограниченную возможность менять цену.","Ko‘p sotuvchi va oson kirish monopolistik raqobatga mos; mahsulot farqlanishi mijoz sadoqatini va cheklangan narx kuchini yaratadi."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-034","d":"medium","sec":160,"k":"D","en":"Many software firms cluster in one district. A specialist college opens and lowers the cost of recruiting trained workers for existing firms, even though each firm keeps the same output and size. Which classification and reason are consistent with this development?","ru":"Многие IT-компании работают в одном районе. Там открывается специализированный колледж, снижающий стоимость найма подготовленных работников, хотя размеры и выпуск каждой компании неизменны. Какая классификация и причина соответствуют ситуации?","uz":"Ko‘plab dasturiy ta’minot firmalari bir hududda jamlangan. Maxsus kollej ochilib, malakali ishchilarni yollash xarajatini kamaytiradi, ammo har firmaning hajmi va ishlab chiqarishi o‘zgarmaydi. Bu qanday hodisa va nega?","options_en":["Internal purchasing economies, because each firm doubles its output","Internal technical economies, because each firm buys a larger machine","Diseconomies of scale, because recruiting becomes more expensive","External economies of scale, because industry clustering provides shared skills"],"options_ru":["Внутренняя экономия закупок, потому что выпуск каждой фирмы удвоился","Внутренняя технологическая экономия, потому что каждая фирма купила большой станок","Отрицательный эффект масштаба, поскольку найм дорожает","Внешняя экономия от масштаба, поскольку кластер даёт доступ к общим навыкам"],"options_uz":["Ichki xarid tejamkorligi, chunki har firma mahsuloti ikki baravar oshdi","Ichki texnik tejamkorlik, chunki har firma katta uskuna sotib oldi","Miqyos samarasizligi, chunki yollash qimmatlashdi","Tashqi miqyos tejamkorligi, chunki tarmoq klasteri umumiy malakalarni yaratadi"],"why":["The source of lower costs is the surrounding industry and training infrastructure, not an individual firm''s enlargement. That is an external economy.","Затраты падают благодаря отраслевому кластеру и образовательной инфраструктуре, а не расширению отдельной фирмы: это внешняя экономия от масштаба.","Xarajat pasayishi alohida firma kattalashgani emas, tarmoq klasteri va ta’lim infratuzilmasidan keladi: tashqi tejamkorlik."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-038","d":"medium","sec":150,"k":"C","en":"A smartphone company keeps its list price unchanged but adds free technical support and a distinctive design, seeking repeat customers. A rival instead lowers its price without changing the product. Which comparison correctly identifies their competitive methods?","ru":"Компания сохраняет цену смартфона, но добавляет бесплатную техническую поддержку и уникальный дизайн ради повторных покупок. Конкурент вместо этого снижает цену, не меняя продукт. Как правильно классифицировать оба способа конкуренции?","uz":"Smartfon firmasi narxni o‘zgartirmay bepul texnik yordam va noyob dizayn qo‘shadi, takror xaridni rag‘batlantiradi. Raqibi esa mahsulotni o‘zgartirmasdan narxni tushiradi. Ularning raqobat usullari qanday farqlanadi?","options_en":["Both compete solely by lowering price","First uses predatory pricing; second uses product differentiation","First uses non-price differentiation; second uses price competition","Both automatically create a legal monopoly"],"options_ru":["Обе конкурируют исключительно снижением цены","Первая применяет хищнические цены, вторая — дифференциацию","Первая использует неценовую дифференциацию, вторая — ценовую конкуренцию","Обе автоматически создают законную монополию"],"options_uz":["Ikkalasi faqat narxni tushirib raqobat qiladi","Birinchisi demping narx qo‘llaydi, ikkinchisi mahsulotni farqlaydi","Birinchisi narxsiz tabaqalanish, ikkinchisi narx raqobatini qo‘llaydi","Ikkalasi avtomatik qonuniy monopoliya yaratadi"],"why":["Design and support change customer value without a list-price cut (non-price competition); the rival''s unchanged product and lower price are price competition.","Дизайн и поддержка повышают ценность товара без снижения цены: неценовая конкуренция. Соперник снижает цену — ценовая конкуренция.","Dizayn va xizmat narxni tushirmasdan qiymat yaratadi — narxsiz raqobat. Raqibning narxni kamaytirishi narx raqobatidir."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-043","d":"medium","sec":155,"k":"B","en":"A juice manufacturer purchases a chain of retail shops that sell its drinks, while a rival juice manufacturer purchases an orchard supplying its fruit. Which pair identifies the direction of integration for the first and second manufacturers?","ru":"Производитель сока покупает сеть розничных магазинов, продающих его напитки. Конкурирующий производитель сока приобретает фруктовый сад — источник сырья. Каковы направления интеграции первого и второго производителей?","uz":"Sharbat ishlab chiqaruvchi uning ichimliklarini sotuvchi chakana do‘konlar tarmog‘ini sotib oladi. Raqib sharbat ishlab chiqaruvchi esa meva yetkazib beruvchi bog‘ni sotib oladi. Birinchi va ikkinchi firmaning integratsiya yo‘nalishi qanday?","options_en":["Both backward vertical integration","Forward vertical; backward vertical","Backward vertical; forward vertical","Both horizontal integration"],"options_ru":["Обе — обратная вертикальная интеграция","Прямая вертикальная; обратная вертикальная","Обратная вертикальная; прямая вертикальная","Обе — горизонтальная интеграция"],"options_uz":["Ikkalasi orqaga vertikal integratsiya","Oldinga vertikal; orqaga vertikal","Orqaga vertikal; oldinga vertikal","Ikkalasi gorizontal integratsiya"],"why":["Buying retailers moves downstream towards customers (forward); buying a fruit supplier moves upstream (backward).","Покупка магазинов — движение к покупателю по цепочке (прямая интеграция), покупка сада — к поставщику (обратная).","Do‘konlarni olish mijozga tomon (oldinga), meva yetkazib beruvchini olish ta’minotga tomon (orqaga) integratsiyadir."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-057","d":"medium","sec":160,"k":"A","en":"A four-firm concentration ratio declines from 80% to 55% after smaller competitors expand. Meanwhile product prices remain unchanged. Which interpretation can be supported by those observations alone?","ru":"После роста небольших конкурентов коэффициент концентрации четырёх крупнейших фирм падает с 80% до 55%. При этом цены товаров не меняются. Какой вывод подтверждается только этими наблюдениями?","uz":"Kichik raqiblar kengaygach, eng yirik to‘rtta firmaning konsentratsiya ko‘rsatkichi 80% dan 55% ga tushdi. Shu bilan birga mahsulot narxlari o‘zgarmadi. Faqat shu ma’lumotlardan qaysi xulosa kelib chiqadi?","options_en":["Market share has become less concentrated among the four largest firms, but price and conduct effects cannot be inferred","Prices must have fallen by exactly 25 percentage points","All collusion must have disappeared by definition","There are now precisely four firms in the market"],"options_ru":["Доля крупнейших четырёх фирм снизилась, но вывод об изменении цен и поведения сделать нельзя","Цены обязательно упали ровно на 25 процентных пунктов","Любой сговор по определению исчез","Теперь на рынке ровно четыре фирмы"],"options_uz":["Eng yirik to‘rt firma ulushi kamaydi, ammo narx va xulq-atvorga ta’sirini aniqlab bo‘lmaydi","Narxlar albatta aynan 25 foiz punktga kamaydi","Har qanday til biriktirish ta’rif bo‘yicha yo‘qoldi","Endi bozorda aynan to‘rtta firma bor"],"why":["CR4 measures the combined market share of the four largest firms. A lower ratio indicates less concentration, not by itself proof of lower prices or no collusion.","CR4 измеряет суммарную долю четырёх крупнейших. Его снижение свидетельствует о меньшей концентрации, но не доказывает падение цен или исчезновение сговора.","CR4 eng yirik to‘rt firmaning jami bozor ulushini o‘lchaydi. Pasayishi konsentratsiya kamayganini bildiradi, narx yoki til biriktirishni isbotlamaydi."]},{"ref":"EC9708:G2:EC9708-G2-T4-P-069","d":"medium","sec":160,"k":"D","en":"A bakery produces 200 loaves with five workers, 228 with six and 245 with seven, using the same equipment. What is the marginal product of the seventh worker, and what happens to marginal product between the sixth and seventh workers?","ru":"Пекарня на неизменном оборудовании выпускает 200 буханок при пяти работниках, 228 при шести и 245 при семи. Какова предельная производительность седьмого работника и как она меняется по сравнению с шестым?","uz":"Nonvoyxona bir xil uskunada besh ishchi bilan 200, olti ishchi bilan 228 va yetti ishchi bilan 245 ta non tayyorlaydi. Yettinchi ishchining chegaraviy mahsuloti qancha va oltinchi ishchiga nisbatan qanday o‘zgaradi?","options_en":["45 loaves; marginal product increases","28 loaves; marginal product is unchanged","17 loaves; marginal product increases","17 loaves; marginal product falls from 28"],"options_ru":["45 буханок; предельная отдача растёт","28 буханок; предельная отдача неизменна","17 буханок; предельная отдача растёт","17 буханок; предельная отдача падает с 28"],"options_uz":["45 non; chegaraviy mahsulot oshadi","28 non; chegaraviy mahsulot o‘zgarmaydi","17 non; chegaraviy mahsulot oshadi","17 non; chegaraviy mahsulot 28 dan tushadi"],"why":["Sixth worker adds 228−200=28 loaves; seventh adds 245−228=17. Marginal labour product decreases with fixed equipment.","Шестой работник добавляет 28 буханок, седьмой 17. При неизменном оборудовании предельная производительность труда снижается.","Oltinchi ishchi 28 ta, yettinchi 17 ta non qo‘shadi. Uskuna o‘zgarmaganda mehnatning chegaraviy mahsuloti kamayadi."]}]'::jsonb;
  item jsonb; v_old bigint; v_new bigint; v_pool bigint; v_order int; v_count int;
  v_correct text; v_i int; v_why_en text; v_why_ru text; v_why_uz text; v_old_key text;
  v_saved_answers int;
BEGIN
  IF jsonb_array_length(payload) <> 28 THEN RAISE EXCEPTION 'expected_28_replacements'; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l
    JOIN public.practice_pools p ON p.id=l.pool_id WHERE p.subject_id=7 AND p.tour_no=4 AND l.is_active;
  IF v_count <> 70 THEN RAISE EXCEPTION 'T4_pool_not_70_before: %',v_count; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(payload)
  LOOP
    v_old_key := item->>'ref'; v_correct := item->>'k';
    IF jsonb_array_length(item->'options_en')<>4 OR jsonb_array_length(item->'options_ru')<>4 OR jsonb_array_length(item->'options_uz')<>4 THEN
      RAISE EXCEPTION 'four_options_required: %',v_old_key;
    END IF;
    IF v_correct NOT IN ('A','B','C','D') OR item->>'d' NOT IN ('medium','hard') THEN RAISE EXCEPTION 'invalid_authoring: %',v_old_key; END IF;
    SELECT q.id INTO STRICT v_old FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=v_old_key;
    SELECT count(*) INTO v_saved_answers FROM public.practice_answers a WHERE a.question_id=v_old;
    IF v_saved_answers > 0 THEN RAISE EXCEPTION 'review_history_bearing_question_before_replacement: %',v_old_key; END IF;
    SELECT l.pool_id,l.order_no INTO STRICT v_pool,v_order FROM public.practice_pool_questions l
      JOIN public.practice_pools p ON p.id=l.pool_id
      WHERE l.question_id=v_old AND l.is_active AND p.subject_id=7 AND p.tour_no=4;
    SELECT id INTO v_new FROM public.questions WHERE subject_id=7 AND book_ref=v_old_key||'-V2';
    IF v_new IS NOT NULL THEN RAISE EXCEPTION 'already_exists: %',v_old_key; END IF;
    v_i := ascii(v_correct)-64;
    v_why_en := item->'why'->>0; v_why_ru := item->'why'->>1; v_why_uz := item->'why'->>2;
    INSERT INTO public.questions (
      subject_id,topic,subtopic,difficulty,qtype,
      question_text,options_text,correct_answer,explanation,image_url,is_active,
      question_text_ru,question_text_uz,question_text_en,
      options_text_ru,options_text_uz,options_text_en,
      explanation_ru,explanation_uz,explanation_en,
      book_ref,time_limit_sec,quality_flag,quality_status
    )
    SELECT
      src.subject_id,src.topic,src.subtopic,item->>'d','mcq',
      item->>'en',(item->'options_en')::text,v_correct,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      NULL,true,item->>'ru',item->>'uz',item->>'en',
      (item->'options_ru')::text,(item->'options_uz')::text,(item->'options_en')::text,
      'Правильный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nПочему: '||v_why_ru,
      'To‘g‘ri javob: '||(item->'options_uz'->>(v_i-1))||E'\nSabab: '||v_why_uz,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      v_old_key||'-V2',(item->>'sec')::int,src.quality_flag,'published'
    FROM public.questions src WHERE src.id=v_old
    RETURNING id INTO v_new;
    UPDATE public.practice_pool_questions SET is_active=false
      WHERE pool_id=v_pool AND question_id=v_old AND is_active;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count<>1 THEN RAISE EXCEPTION 'old_link_not_one: %',v_old_key; END IF;
    INSERT INTO public.practice_pool_questions (pool_id,question_id,order_no,is_active)
      VALUES (v_pool,v_new,v_order,true);
    INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
      VALUES(v_old,v_new,'replacement','Economics Gen2: actual editorial difficulty upgrade, T4 governed practice, originals retained');
    FOR v_i IN 1..4 LOOP
      INSERT INTO public.question_answer_diagnostics(
        question_id,answer_kind,answer_key,answer_value,is_correct,
        mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,
        next_action_ru,next_action_uz,next_action_en,rule_json,quality_status
      )
      SELECT v_new,'mcq_option',chr(64+v_i),NULL,(chr(64+v_i)=v_correct),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'multi_step_economic_reasoning' END,
        src.subtopic,
        'Выбранный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nОбъяснение: '||v_why_ru||E'\nПравильный ответ: '||(item->'options_ru'->>(ascii(v_correct)-65)),
        'Tanlangan javob: '||(item->'options_uz'->>(v_i-1))||E'\nIzoh: '||v_why_uz||E'\nTo‘g‘ri javob: '||(item->'options_uz'->>(ascii(v_correct)-65)),
        'Selected answer: '||(item->'options_en'->>(v_i-1))||E'\nReason: '||v_why_en||E'\nCorrect answer: '||(item->'options_en'->>(ascii(v_correct)-65)),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Повторите метод решения и проверьте каждый шаг.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Yechim usulini takrorlang va har bir bosqichni tekshiring.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Review the method and check each step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_T4P'||substring(v_old_key from 'P-([0-9]{3})')||'_V2_'||chr(64+v_i)),
        'published'
      FROM public.questions src WHERE src.id=v_old;
    END LOOP;
  END LOOP;
  -- Existing unchanged T4 items receive academically reviewed metadata, not fabricated all-medium labels.
  UPDATE public.questions q SET difficulty=CASE
    WHEN right(q.book_ref,3) IN ('001','002','003','006','010','013','018','019','020','022','023','024','026','029','036','039','040','041','044','049','050','054') THEN 'medium'
    ELSE 'easy' END
    WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T4-P-[0-9]{3}$'
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(payload) j WHERE j->>'ref'=q.book_ref);
  GET DIAGNOSTICS v_count=ROW_COUNT;
  IF v_count<>42 THEN RAISE EXCEPTION 'unchanged_count_expected42: %',v_count; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    WHERE p.subject_id=7 AND p.tour_no=4 AND l.is_active;
  IF v_count<>70 THEN RAISE EXCEPTION 'active_pool_not70_after: %',v_count; END IF;
  IF EXISTS (
    SELECT 1 FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
       JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=4 AND l.is_active
    GROUP BY 1 HAVING count(*)<>70
  ) THEN RAISE EXCEPTION 'pool_count_inconsistent'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=4 AND l.is_active AND q.difficulty='easy') <> 20
    THEN RAISE EXCEPTION 'difficulty_easy_not20'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=4 AND l.is_active AND q.difficulty='medium') <> 30
    THEN RAISE EXCEPTION 'difficulty_medium_not30'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=4 AND l.is_active AND q.difficulty='hard') <> 20
    THEN RAISE EXCEPTION 'difficulty_hard_not20'; END IF;
END $reb$;
COMMIT;
